import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { createJob, getJob, isWorkerUp, listJobs } from './jobs.ts';
import { parseSubmission, type FieldError } from './validation.ts';

const MAX_BODY_BYTES = 16 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error }, headers);
}

/** Reads the whole body. Resolves to null when it exceeds MAX_BODY_BYTES (the rest is drained). */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const parsed = parseSubmission(req.headers['content-type'], raw, req.headers['idempotency-key']);
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', parsed.fields);
    return;
  }
  const { input, steps, failAttempts, idempotencyKey } = parsed.value;
  const result = createJob(db, { input, steps, failAttempts, idempotencyKey });
  if (result.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, result.kind === 'created' ? 201 : 200, result.job);
}

function route(req: IncomingMessage, res: ServerResponse): Promise<void> | void {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  const methodNotAllowed = (allow: string) =>
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`, undefined, { allow });

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed('GET');
    return send(res, 200, { status: 'ok', worker: isWorkerUp(db) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed('GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobs(db) });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed('GET, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed('GET');
    const job = getJob(db, match[1]!);
    if (!job) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, job);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => route(req, res))
    .catch((e: unknown) => {
      console.error('request failed:', e);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
      else res.end();
    });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

